//! Reading synthetic Power Pivot workbooks (`bicraft_powerpivot::synthetic`): the model, every
//! table's values, the errors for a workbook without a model and for broken backups, and the
//! committed fixture `crates/powerpivot/tests/fixtures/sales.xlsx` regenerated byte for byte.

use bicraft_model::DataType;
use bicraft_powerpivot::{Error, Limits, read_backup, read_workbook, synthetic};
use bicraft_vertipaq::CellValue;

fn fixture_path() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/sales.xlsx")
}

#[test]
fn the_sample_workbook_reads_back() {
    let bytes = synthetic::sample().unwrap();
    let wb = read_workbook(&bytes, &Limits::default()).unwrap();
    assert!(wb.warnings.is_empty(), "{:?}", wb.warnings);
    assert_eq!(wb.compatibility_level, Some(1103));
    let m = &wb.model;
    let names: Vec<&str> = m.tables.iter().map(|t| t.name.as_str()).collect();
    assert_eq!(names, ["Product", "Sales"]);
    let product = m.table("Product").unwrap();
    let cols: Vec<(&str, DataType)> = product
        .columns
        .iter()
        .map(|c| (c.name.as_str(), c.data_type))
        .collect();
    assert_eq!(
        cols,
        [
            ("ProductKey", DataType::Int64),
            ("Name", DataType::String),
            ("Category", DataType::String),
            ("Unit price", DataType::Decimal)
        ]
    );
    assert!(product.columns[0].is_hidden);
    assert_eq!(product.columns[3].source_column.as_deref(), Some("Unit price"));
    let h = &product.extra["hierarchies"][0];
    assert_eq!(h["name"], "Catalogue");
    assert_eq!(h["levels"][1]["column"], "Name");
    let sales = m.table("Sales").unwrap();
    let line = sales.column("Line total").unwrap();
    assert_eq!(
        line.expression.as_deref(),
        Some("Sales[Quantity] * RELATED(Product[Unit price])")
    );
    assert_eq!(
        line.data_type,
        DataType::Double,
        "a calculated column gets its storage type"
    );
    let measures: Vec<(&str, &str)> = sales
        .measures
        .iter()
        .map(|x| (x.name.as_str(), x.expression.as_str()))
        .collect();
    assert_eq!(
        measures,
        [
            ("Total amount", "SUM(Sales[Amount])"),
            ("Units", "SUM('Sales'[Quantity])")
        ]
    );
    assert_eq!(m.relationships.len(), 1);
    let r = &m.relationships[0];
    assert_eq!(
        (
            r.from_table.as_str(),
            r.from_column.as_str(),
            r.to_table.as_str(),
            r.to_column.as_str()
        ),
        ("Sales", "ProductKey", "Product", "ProductKey")
    );
    assert!(r.is_active);
    let p = &sales.partitions[0];
    assert_eq!(p.source_type, "m");
    assert!(
        p.expression
            .as_deref()
            .unwrap()
            .contains("//   SELECT * FROM [Sales]")
    );

    // every value, as the synthetic model holds it
    let model = synthetic::sample_model();
    for (t, rows) in model.tables.iter().zip(&wb.tables) {
        assert_eq!(t.name, rows.name);
        assert_eq!(rows.columns.len(), t.columns.len());
        for (c, (name, values)) in t.columns.iter().zip(&rows.columns) {
            assert_eq!(&c.name, name);
            assert_eq!(&c.values, values, "{}[{}]", t.name, c.name);
        }
    }
    assert_eq!(wb.tables[1].rows(), 240);
    assert!(wb.tables[1].columns[3].1.contains(&CellValue::Null));
}

#[test]
fn the_committed_fixture_is_the_sample() {
    let bytes = synthetic::sample().unwrap();
    let path = fixture_path();
    if std::env::var_os("BICRAFT_BLESS").is_some() {
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, &bytes).unwrap();
    }
    let committed = std::fs::read(&path).expect("tests/fixtures/sales.xlsx (BICRAFT_BLESS=1 writes it)");
    assert!(
        committed == bytes,
        "the fixture differs from synthetic::sample(); bless it again"
    );
}

#[test]
fn a_workbook_without_a_model_is_refused_clearly() {
    let bytes = synthetic::without_model().unwrap();
    let err = read_workbook(&bytes, &Limits::default()).unwrap_err();
    assert_eq!(err, Error::NoDataModel);
    assert!(err.to_string().contains("no Power Pivot data model"));
    assert!(matches!(
        read_workbook(b"not a zip", &Limits::default()),
        Err(Error::NotWorkbook(_))
    ));
}

#[test]
fn broken_backups_give_errors_or_warnings() {
    let item = synthetic::backup(&synthetic::sample_model()).unwrap();
    assert!(read_backup(&item, &Limits::default()).is_ok());
    // a cap on cells
    let tight = Limits {
        max_cells: 100,
        ..Limits::default()
    };
    assert!(matches!(read_backup(&item, &tight), Err(Error::Limit(_))));
    // truncated, and zeroed in the files section
    assert!(read_backup(&item[..item.len() / 2], &Limits::default()).is_err());
    let mut damaged = item.clone();
    for b in damaged.iter_mut().skip(5000).take(3000) {
        *b = 0;
    }
    // damage gives an error or a warning, never a silent success
    if let Ok(wb) = read_backup(&damaged, &Limits::default()) {
        assert!(!wb.warnings.is_empty());
    }
}
